import * as React from 'react';
import { CommonProps } from '../utility/commonProps';
export type DisplayTagColor = 'red' | 'spark' | 'green' | 'blue' | 'purple' | 'gray';
export interface DisplayTagProps extends Omit<React.ComponentPropsWithoutRef<'span'>, 'className' | 'style'>, CommonProps {
    /**
     * The content for the DisplayTag.
     */
    children: React.ReactNode;
    /**
     * The color for the DisplayTag.
     */
    color?: DisplayTagColor;
    /**
     * The leading content for the DisplayTag.
     */
    leading?: React.ReactNode;
}
/**
 * DisplayTags are used to display data with positive or negative values.They are visual only and non-interactive.
 *
 *
 * ### Content
 *
 * #### Leading icon
 *
 * The DisplayTag accepts number or string, depending on the value it will show up or down arrow, denoting positive or negative values respectively:
 *
 * ```tsx
 * import * as React from "react";
 * import * as Icon from "@livingdesign/icons";
 * import { DisplayTag } from "@walmart-dataventures/shared-components";
 *
 * export default () => {
 *   return (
 *     <DisplayTag leading={<Icon.Wallet />}>
 *          DisplayTag Content
 *     </DisplayTag>
 *   );
 * };
 * ```
 *
 * ### Features
 *
 * #### Color
 *
 * DisplayTag comes in six colors:
 *
 * ```tsx
 * <DisplayTag color="purple">DisplayTag Content</Tag> (default)
 * <DisplayTag color="blue">DisplayTag Content</Tag>
 * <DisplayTag color="green">DisplayTag Content</Tag>
 * <DisplayTag color="red">DisplayTag Content</Tag>
 * <DisplayTag color="spark">DisplayTag Content</Tag>
 * <DisplayTag color="gray">DisplayTag Content</Tag>
 * ```
 *
 */
export declare const DisplayTag: React.FunctionComponent<DisplayTagProps>;
